(* [comment removed for export] *)
Lemma mb_shl3_shr3 : forall x, 0 <= x -> Z.shiftl (Z.shiftr x 3) 3 = x - x mod 8.
Proof.
  intros x Hx. rewrite Z.shiftr_div_pow2, Z.shiftl_mul_pow2 by lia. change (2 ^ 3) with 8.
  pose proof (Z.div_mod x 8 ltac:(lia)). lia.
Qed.
Lemma mb_shr3_shr61 : forall x, 0 <= x < 2^64 -> Z.shiftr (Z.shiftr x 3) 61 = 0.
Proof. intros x Hx. rewrite Z.shiftr_shiftr by lia. change (3 + 61) with 64. rewrite Z.shiftr_div_pow2 by lia. apply Z.div_small. lia. Qed.
Lemma mballoc_round2 : forall n, 0 <= n -> n + 31 < 2^61 -> Z.shiftl (Z.shiftr (n + 31) 3) 3 = mb_block_size n.
Proof. intros n H0 H1. rewrite mb_shl3_shr3 by lia. rewrite mb_block_size_eq by lia. reflexivity. Qed.

