Lemma mballoc_round : forall n, 0 <= n -> n + 31 < 2^61 -> Z.land (n + 31) 4611686018427387896 = mb_block_size n.
Proof. intros n H0 H1. rewrite mb_land_M8' by lia. rewrite mb_block_size_eq by lia. reflexivity. Qed.

